function updateAnglePreview(source){const value=source.value===''?NaN:Number(source.value),patch=anglePatch(value);if(source.id==='model-angle-slider')$('model-angle-input').value=source.value;else if(Number.isFinite(value))$('model-angle-slider').value=String(value);$('model-angle-apply').disabled=!patch;$('model-angle-message').textContent=patch?'模型同步預覽；套用後重算魚口。':'請輸入 5° 到 175° 的有效角度。';if(!patch){modelEditor.cancelDrag();viewer.render();return;}modelEditor.preview(patch);$('model-edit-state').textContent='角度預覽 · 套用後重算魚口';const a=value*Math.PI/180,x=65+45*Math.cos(a),y=74-45*Math.sin(a);$('model-angle-sketch').innerHTML=`<path d="M8 74H124" stroke="#8096a9" stroke-width="8"/><path d="M65 74L${x} ${y}" stroke="#258fbc" stroke-width="12"/><path d="M90 74A25 25 0 ${value>180?1:0} 0 ${65+25*Math.cos(a)} ${74-25*Math.sin(a)}" fill="none" stroke="#bc861b" stroke-width="2"/><text x="93" y="62" fill="#24465f" font-size="12">${fmt(value,1)}°</text>`;}
