function modelHandleKeyboard(kind,event){const direction=['ArrowLeft','ArrowDown'].includes(event.key)?-1:['ArrowRight','ArrowUp'].includes(event.key)?1:0;if(!direction||modelEditor.locked)return false;const p=state.params,n=direction*(event.shiftKey?5:1);if(kind==='direction'){const f=positioningFrame(p);if(!f)return false;const next={...p,angle:p.angle+n};if(p.hostType!=='straight'&&['ArrowLeft','ArrowRight'].includes(event.key)){next.angle=p.angle;next.branchSwivel=p.branchSwivel+n;}const vector=positioningFrame(next)?.direction,patch=vector?directionFromWorldVector(p,vector):null;if(patch)commitModelPatch(patch);}else{const map=p.hostType==='elbow'?(event.altKey?'elbow-clock':'elbow-position'):p.hostType==='cone'?(event.altKey?'cone-clock':'cone-position'):(event.altKey?'straight-clock':'straight-position');applyVisual(visualKeyboardAction(map,event.key,p,{shiftKey:event.shiftKey}));}return true;}

