function elbowRadiusMarkup(){const p=state.params,mode=inputSetup.radiusMode??'custom',nps=inputSetup.mainSize;return `<div class="field full"><label for="elbow-radius-mode">彎頭半徑</label><select id="elbow-radius-mode" name="elbowRadiusMode">${[['lr','長半徑 LR'],['sr','短半徑 SR']].map(([k,t])=>{const r=nominalElbowRadius(nps,k,p.bendAngle);return `<option value="${k}"${mode===k?' selected':''}${r===null?' disabled':''}>${t}${r===null?' · 無此尺寸預設':` · R ${fmt(r)} mm`}</option>`;}).join('')}<option value="custom"${mode==='custom'?' selected':''}>依供料／實測半徑</option></select><output class="pipe-od-readback">中心線彎曲半徑 R ${fmt(p.bendRadius)} mm</output>${mode==='custom'?numberField('bendRadius','中心線彎曲半徑','mm','使用圓弧中心到管中心線的距離；不是外背半徑。',true):'<small>帶入 Benkan 90° 公稱 A 尺寸，作理想模型基準；需配合供料尺寸。</small>'}${p.bendAngle===45?'<small>45° 型採自訂理想圓弧；請確認供料曲率，不把中心至端面 B 當成半徑。</small>':''}</div>`;}
function elbowInputDiagram(){const p=state.params,rad=d=>d*Math.PI/180,k=82/p.bendRadius,R=p.mainOD/2,point=(b,r)=>[32+(p.bendRadius+r)*Math.sin(b)*k,147-(p.bendRadius-(p.bendRadius+r)*Math.cos(b))*k],path=r=>Array.from({length:33},(_,i)=>point(rad(p.bendAngle)*i/32,r).map(v=>fmt(v,2)).join(',')).map((q,i)=>(i?'L':'M')+q).join(' '),b=rad(p.bendPosition),q=point(b,0),end=point(rad(p.bendAngle),0),phi=rad(p.surfaceClock),aligned=p.elbowAlignment&&p.elbowAlignment!=='free',contact=point(b,R),ref=p.elbowAlignment?.startsWith('a-')?point(0,0):end,mark=aligned?contact:q,axis=aligned?`<path d="M${ref[0]} ${ref[1]}L${contact[0]} ${contact[1]}" fill="none" stroke="#b06c12" stroke-width="2" stroke-dasharray="4 3"/><text x="${p.elbowAlignment?.startsWith('a-')?70:contact[0]+7}" y="${p.elbowAlignment?.startsWith('a-')?136:(ref[1]+contact[1])/2}">同軸</text>`:'';return `<svg viewBox="0 0 280 175" role="img" aria-label="${aligned?elbowAlignmentLabel(p)+'；虛線為端部中心線':'彎頭從 A 端起定位'}；截面從 A 朝 B 看，外背在上"><path d="${path(R)}" fill="none" stroke="#8ba2b8"/><path d="${path(-R)}" fill="none" stroke="#8ba2b8"/><path d="${path(0)}" fill="none" stroke="#8ba2b8" stroke-dasharray="3 3"/>${axis}<circle cx="${mark[0]}" cy="${mark[1]}" r="5" fill="#1764ad"/><text x="15" y="167">A 端起量</text><text x="${end[0]+5}" y="${end[1]-6}">B 端</text><text x="30" y="18">${fmt(p.bendPosition)}° 截面</text><circle cx="218" cy="88" r="34" fill="#ecf3f9" stroke="#8ba2b8"/><circle cx="${218-34*Math.sin(phi)}" cy="${88-34*Math.cos(phi)}" r="5" fill="#1764ad"/><text x="218" y="43" text-anchor="middle">外背 0°</text><text x="218" y="142" text-anchor="middle">內腹 180°</text><text x="174" y="92" text-anchor="end">90°</text><text x="258" y="92">270°</text><text x="198" y="166" text-anchor="middle" font-size="9">截面：從 A 朝 B 看；非比例</text></svg>`;}
function elbowPositionMarkup(){const p=state.params,aligned=p.elbowAlignment!=='free';return elbowPositionPicker(p)+(aligned?'':surfaceClockPicker(p))+`<details id="elbow-exact" class="advanced-settings"><summary>精確定位與間隙</summary><div class="fields-grid">${aligned?'':numberField('bendPosition','A 端起的截面角度','°')+numberField('surfaceClock','插接側面角度','°')+numberField('branchSwivel','支管側向旋轉','°','0° 在當地切線與外法線平面；搭配 3D 核對。')}${p.jointType==='on'?numberField('rootGap','外貼徑向間隙'):numberField('projection','內插凸入深度','mm','由近側內壁沿支管軸向伸入')}${closedMother()?'':numberField('holeGap','孔口每側間隙')}</div></details>`;}
function straightPositionMarkup(){return straightPositionPicker(state.params)+surfaceClockPicker(state.params)+`<details id="straight-exact" class="advanced-settings"><summary>精確定位、偏心與間隙</summary><div class="fields-grid">${numberField('azimuth','繞主管方位','°','含偏心時與圖中的實際外壁方位不同')}${numberField('offset','偏心量','mm','局部側向偏移')}${state.params.jointType==='on'?numberField('rootGap','外貼徑向間隙'):numberField('projection','內插凸入深度')}${numberField('holeGap','孔口每側間隙')}${surfacePositionField()}</div><details><summary>舊專案座標</summary>${numberField('jointPosition','主管中心面轴基準 X','mm','虛擬中心面座標，與外壁入點不同',true)}</details></details>`;}



function conePositionMarkup(){return conePositionPicker(state.params)+surfaceClockPicker(state.params)+`<details id="cone-exact" class="advanced-settings"><summary>精確定位、側轉與間隙</summary><div class="fields-grid">${numberField('jointPosition','A 端沿軸向量到接觸點')}${numberField('surfaceClock','母材截面方位','°','由 A 朝 B 看，0° 上、90° 左')}${numberField('branchSwivel','支管側向旋轉','°')}${state.params.jointType==='on'?numberField('rootGap','外貼法向間隙'):numberField('projection','近侧内壁起沿支管軸凸入量')}${closedMother()?'':numberField('holeGap','孔口每側間隙')}</div></details>`;}
function padMarkup(){const p=state.params;if(isSteelSection(p))return '<p class="field-note">鋼構支材目前直接裁切貼合母管；尚未提供墊座、加勁板或補強板製作圖。母管保持封閉。</p>';if(p.hostType==='cone')return '<p class="field-note">大小管的補強板仍需另作成形設計；目前可製作支管魚口與母材孔口的真實扇環紙樣。</p>';const elbow=p.hostType==='elbow';return `<label class="check-field"><input type="checkbox" name="padEnabled"${p.padEnabled?' checked':''}>加入補強板</label><div id="pad-fields"${p.padEnabled?'':' hidden'}>${elbow?'<p class="field-note">使用已成形的雙曲率板貼合彎頭；孔沿支管軸穿過板厚。提供 3D 與分點定位工單。外形圖卡表示定位座標中的輪廓。</p>':selectField('padManufacturing','補強板怎麼做？',[['neutral','平板切好後捲彎'],['formed-normal','已彎板：沿板厚法線切孔']])}${padShapeCards(p)}${padSplitIllustration(p)}<div class="fields-grid">${numberField('padThickness','補強板厚度')}${numberField('padMargin','最低留邊','mm',elbow?'包含連續板厚的保守幾何留邊':'孔緣至外緣')}${numberField('padClearance','板孔每側間隙')}${elbow||p.padManufacturing==='formed-normal'?'':numberField('kFactor','中性層係數 K','','0–1；需成形校正')}</div><p class="field-note">尺寸越界或留邊不足會停止出圖。板形與幾何留邊不等於承壓、補強面積或焊接強度核准。</p></div>`;}
