  $('parameter-form').innerHTML=`<nav class="config-nav" aria-label="設定步驟">${panelNames.map((name,i)=>`<button type="button" data-setting-panel="${i}" aria-current="${state.settingPanel===i?'step':'false'}">${name}</button>`).join('')}</nav>`+groups.map((html,i)=>i<2?`<section class="form-group" data-step="${i}" data-config-panel="${i}"${state.settingPanel===i?'':' hidden'}><h3>${panelNames[i]}</h3>${html}${i===0?measuredDiameterHelper:''}</section>`:`<details id="settings-${i}" class="option-fold" data-config-panel="${i}" open${state.settingPanel===i?'':' hidden'}><summary>${panelNames[i]}${i===2&&p.padEnabled?'<span class="summary-value">已加入補強板</span>':''}</summary><section class="form-group" data-step="${i}">${html}</section></details>`).join('');
  for(const [id,open] of folds)if($(id))$(id).open=open;
  if(elbow&&p.elbowAlignment!=='free')for(const key of ['angle','bendPosition','surfaceClock','branchSwivel'])if($('param-'+key))$('param-'+key).disabled=true;
  const samples=$('param-samples');if(samples){if(![...samples.options].some(o=>Number(o.value)===p.samples))samples.add(new Option(`${p.samples} 點`,p.samples));samples.value=String(p.samples);}
  $('steps').innerHTML=steps.map((text,i)=>`<button type="button" data-step-button="${i}" aria-pressed="${state.mode==='guided'&&i===state.step}"><span class="step-number">${i+1}</span>${text}</button>`).join('');
  document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode)));
  $('previous-step').disabled=state.step===0;$('next-step').disabled=state.step===steps.length-1&&(pending||!!state.fabricationError||!fabricationReadiness(state.result).ready);$('next-step').textContent=state.step===steps.length-1?'製作報告':'下一步';document.querySelector('.step-actions').hidden=state.mode==='expert';displayErrors();restoreFocus(focus);updateEditingPreview();syncModelControls();
