  if(r.valid&&!(r.params.hostType==='elbow'&&(state.template==='elbow-location'||(state.template==='elbow-pad-location'&&!!r.geometry?.pad)))&&!paperTemplates().some(t=>t.id===state.template))state.template=paperTemplates()[0]?.id??'';
